INSERT INTO passages (id, source_id, text, section, tokens) VALUES
  ('src-policy-index-p0001', 'src-policy-index', '機會，給出來 陪伴，不孤單 教育政策 破解北市教職流失與校園危機 沈伯洋提教育四大支持 教育政策
