INSERT INTO passages (id, source_id, text, section, tokens) VALUES
  ('src-policy-04-p0001', 'src-policy-04', '串起城市歷史與山林 沈伯洋推四大文化徑、三大登山中心：打造亞洲第一觀光登山城', '台北文化徑×山林徑', '串 起 城市 歷 史 與 山 林 串起 起城 市歷 歷史 史與 與山 山林 沈伯洋 推 四 大 文化徑 沈伯 伯洋 洋推 推四 四大 大文 文化 化徑 三 登 中 心 三大 大登 登山 山中 中心 打 造 亞 洲 第 一 觀 光 城 打造 造亞 亞洲 洲第 第一 一觀 觀光 光登 山城' )
