INSERT INTO passages (id, source_id, text, section, tokens) VALUES
  ('src-policy-05-p0005', 'src-policy-05', '都市微森林將以四項改革任務推動，從制度、科技、參與到循環，全面升級台北的都市林治理。', '04｜政策內容', '都市微森林 將 以 四 項 改 革 任 務 推 動 都市 市微 微森 森林 林將 將以 以四 四項 項改 改革 革任 任務 務推 推動 從 制 度 從制 制度 科 技 科技 參 與 到 循 環 參與 與到 到循 循環 全 面 升 級 台北 的 都 市 林 治 理 全面 面升 升級 級台 北的 的都 市林 林治 治理' )
