INSERT INTO passages (id, source_id, text, section, tokens) VALUES
  ('src-policy-07-p0001', 'src-policy-07', '沈伯洋發佈運動政見 將推國際足球場 超級市民運動中心', '運動政策', '沈伯洋 發 佈 運動 政見 沈伯 伯洋 洋發 發佈 佈運 動政 將 推 國 際 足 球 場 將推 推國 國際 際足 足球 球場 超 級 市民 中 心 超級 級市 民運 動中 中心' )
