INSERT INTO passages (id, source_id, text, section, tokens) VALUES
  ('src-heart-quiz-1-p0002', 'src-heart-quiz-1', 'H 空間 打造亞洲第一登山觀光城，讓山徑成為城市日常 建構首都文化徑，串起台北文化底蘊 培育都市微森林，為城市添綠降溫 點我看更多
