INSERT INTO passages (id, source_id, text, section, tokens) VALUES
  ('src-entry-talks-13-2d3866fb6f-p0011', 'src-entry-talks-13-2d3866fb6f', '\[00:23:51\] 奧迪： 你們到現在還會有熱戀的愛情感覺嗎？
