INSERT INTO passages (id, source_id, text, section, tokens) VALUES
  ('src-entry-talks-13-2d3866fb6f-p0017', 'src-entry-talks-13-2d3866fb6f', '\[00:42:15\] 沈伯洋： 我每天都對老婆說「我愛你」，一天七、八次跑不掉。
