INSERT INTO passages (id, source_id, text, section, tokens) VALUES
  ('src-entry-talks-13-2d3866fb6f-p0022', 'src-entry-talks-13-2d3866fb6f', '\[00:56:56\] 沈伯洋： 我很像電動裡面的「坦（Tank）」，坦在最前面承受攻擊，隊友才能進攻補血。
