INSERT INTO passages (id, source_id, text, section, tokens) VALUES
  ('src-entry-talks-24-af6058b812-p0030', 'src-entry-talks-24-af6058b812', '\[00:48:14\] 黃暐瀚：地方可能要精進的？
我覺得因為我做的那一個
