INSERT INTO passages (id, source_id, text, section, tokens) VALUES
  ('src-entry-talks-39-e988e9712f-p0001', 'src-entry-talks-39-e988e9712f', '編按：本文依據華視《三國演議》（2025 年 11 月 22 日，主持人汪浩、矢板明夫）專訪逐字稿整理改寫，以第一人稱呈現沈伯洋（Puma）的論點。
