INSERT INTO passages (id, source_id, text, section, tokens) VALUES
  ('src-entry-talks-40-eca16a2f3f-p0016', 'src-entry-talks-40-eca16a2f3f', '沈伯洋以實體出席德國國會回應中共通緝，並把焦點從自身拉回每一位台灣人：看清中國做得到與做不到的事、讓每一次恫嚇都付出代價，才是台灣心防與第一島鏈韌性的起點。
